"""Four-language, independently authored noun explanations; source links are references."""
LANGS=('ru','uk','en','sv')
def T(r,u,e,s):return dict(zip(LANGS,(r,u,e,s)))
def S(s):return T(s,s,s,s)
def E(s,r,u,e):return dict(sv=s,meaning=T(r,u,e,s))
def L(s,r,u,e,**kw):return dict(sv=s,ru=r,uk=u,en=e,**kw)
def W(s,r,u,e):return dict(sv=s,meaning=T(r,u,e,s))
def build_theory():
 c=dict(description=T('Научись называть людей, вещи и места: запоминай род со словом и используй его в живой речи.','Навчися називати людей, речі й місця: запам’ятовуй рід разом зі словом і використовуй його в мовленні.','Learn to name people, things and places: learn gender with each word and use it in real speech.','Lär dig att benämna människor, saker och platser: lär in genus med ordet och använd det i samtal.'),goals=[
 T('Узнавать существительные и учить их вместе с en или ett.','Розпізнавати іменники й учити їх разом з en або ett.','Recognise nouns and learn them with en or ett.','Känna igen substantiv och lära in dem med en eller ett.'),
 T('Представлять новый предмет и говорить об уже известном.','Представляти новий предмет і говорити про вже відомий.','Introduce a new item and refer to a known one.','Presentera en ny sak och tala om en känd sak.'),
 T('Понимать простые формы числа и согласовывать stor и röd.','Розуміти прості форми числа й узгоджувати stor та röd.','Understand basic number forms and agree stor and röd.','Förstå enkla numerusformer och böja stor och röd.'),
 T('Заказывать в кафе, покупать вещи и описывать жильё.','Замовляти в кафе, купувати речі й описувати житло.','Order in a café, buy things and describe a home.','Beställa på kafé, köpa saker och beskriva en bostad.')],sections=[],tables=[],questions=[],writing=[])
 for id,title in [('basics',T('1. Что такое существительное','1. Що таке іменник','1. What a noun is','1. Vad ett substantiv är')),('gender',T('2. Род: правила и границы','2. Рід: правила й межі','2. Gender: patterns and limits','2. Genus: mönster och gränser')),('usage',T('3. Когда нужен артикль','3. Коли потрібен артикль','3. When an article is needed','3. När behövs en artikel?')),('forms',T('4. Связь с другими формами','4. Зв’язок з іншими формами','4. Connections to other forms','4. Samband med andra former')),('reference',T('5. Исключения и шпаргалка','5. Винятки й шпаргалка','5. Exceptions and reference','5. Undantag och snabbguide'))]:c['sections'].append(dict(id=id,title=title,rules=[]))
 def R(sec,id,title,text,theory,pattern,examples,comparison,mistakes,limits,prompt,answer,explanation,level='A',sources=None):
  next(s for s in c['sections'] if s['id']==sec)['rules'].append(dict(id=id,title=title,text=text,theory=theory,pattern=pattern,examples=examples,comparison=comparison,mistakes=mistakes,limits=limits,mini=dict(prompt=prompt,answer=answer,explanation=explanation),level=level,sources=sources or ['sag-nouns','saol']))
 R('basics','noun',T('Существительное: название','Іменник: назва','A noun names something','Substantiv benämner något'),
 T('Substantiv называет человека, животное, предмет, место или понятие. Вопросы «кто?» и «что?» помогают найти многие существительные: en lärare, en katt, en bok, ett kök, en tid.','Substantiv називає людину, тварину, предмет, місце або поняття. Питання «хто?» і «що?» допомагають знайти багато іменників: en lärare, en katt, en bok, ett kök, en tid.','A substantiv names a person, animal, object, place or concept: en lärare, en katt, en bok, ett kök, en tid. Asking who or what can help you find a noun.','Ett substantiv benämner en person, ett djur, en sak, en plats eller ett begrepp: en lärare, en katt, en bok, ett kök, en tid. Frågorna vem och vad kan hjälpa dig.'),
 T('Это часть речи, а не только «вещь, которую можно потрогать». Tid — время — тоже существительное. Названия Stockholm и Sara — имена собственные; перед ними обычно нет en/ett.','Це частина мови, а не лише «річ, якої можна торкнутися». Tid — час — теж іменник. Stockholm і Sara — власні назви; перед ними зазвичай немає en/ett.','This is a word class, not just a touchable thing. Tid means time and is also a noun. Stockholm and Sara are proper names and normally take no en/ett.','Det är en ordklass, inte bara sådant som går att ta på. Tid är också ett substantiv. Stockholm och Sara är egennamn och har normalt inte en eller ett framför sig.'),S('en lärare · en katt · en bok · ett kök · tid'),[E('En katt sover.','Кошка спит.','Кішка спить.','A cat is sleeping.'),E('Vi har tid.','У нас есть время.','Ми маємо час.','We have time.')],T('Bok называет предмет; läsa — действие; stor — свойство.','Bok називає предмет; läsa — дію; stor — властивість.','Bok names an object; läsa an action; stor a property.','Bok benämner en sak, läsa en handling och stor en egenskap.'),T('Не называй stor существительным только потому, что оно стоит рядом с bok.','Не називай stor іменником лише тому, що воно стоїть біля bok.','Stor is not a noun just because it appears beside bok.','Stor blir inte substantiv för att det står bredvid bok.'),T('Вопросы кто/что — подсказка, а не полное определение части речи.','Питання хто/що — підказка, а не повне визначення частини мови.','Who/what questions are a clue, not a complete word-class test.','Frågorna vem/vad är ett stöd, inte ett fullständigt ordklasstest.'),T('Найди существительное: Vi läser en bok.','Знайди іменник: Vi läser en bok.','Find the noun: Vi läser en bok.','Hitta substantivet: Vi läser en bok.'),'bok',T('Bok называет то, что мы читаем.','Bok називає те, що ми читаємо.','Bok names what we read.','Bok benämner det vi läser.'))
 R('basics','roles',T('Существительное в предложении','Іменник у реченні','A noun in a sentence','Substantiv i en mening'),
 T('Существительное может называть того, кто действует, или то, на что направлено действие. После предлога оно часто указывает место: i ett rum.','Іменник може називати того, хто діє, або те, на що спрямована дія. Після прийменника він часто вказує місце: i ett rum.','A noun can name the doer or the thing affected. After a preposition it can give a place: i ett rum.','Ett substantiv kan ange vem som gör något eller vad handlingen gäller. Efter en preposition kan det ange plats: i ett rum.'),
 T('В En lärare läser en bok подлежащее — en lärare, дополнение — en bok. Артикль зависит от слова, а не от его роли. В обычном утверждении нужен и глагол.','У En lärare läser en bok підмет — en lärare, додаток — en bok. Артикль залежить від слова, а не від його ролі. Звичайне твердження потребує й дієслова.','In En lärare läser en bok, en lärare is the subject and en bok the object. The article follows the noun’s gender, not its sentence role. A normal statement also needs a verb.','I En lärare läser en bok är en lärare subjekt och en bok objekt. Artikeln beror på ordets genus, inte satsdelen. Ett vanligt påstående behöver också ett verb.'),S('subjekt → presens → objekt / plats'),[E('Ett barn läser en bok.','Ребёнок читает книгу.','Дитина читає книжку.','A child is reading a book.'),E('Hon sitter i ett rum.','Она сидит в комнате.','Вона сидить у кімнаті.','She is sitting in a room.')],T('Jag ser ett barn / Ett barn ser mig: род barn один и тот же.','Jag ser ett barn / Ett barn ser mig: рід barn той самий.','Jag ser ett barn / Ett barn ser mig: barn keeps its gender.','Jag ser ett barn / Ett barn ser mig: barn har samma genus.'),T('En bok på bordet — словосочетание. Полное сообщение: En bok ligger på bordet.','En bok på bordet — словосполучення. Повне повідомлення: En bok ligger på bordet.','En bok på bordet is a phrase. A statement is En bok ligger på bordet.','En bok på bordet är en fras. En bok ligger på bordet är ett påstående.'),T('Предлоги i и på выбираются по ситуации, а не по en/ett.','Прийменники i та på залежать від ситуації, а не від en/ett.','Choose i or på for the situation, not for gender.','Valet av i eller på beror på sammanhanget, inte genus.'),T('Собери: hon / köper / en stol.','Склади: hon / köper / en stol.','Build: hon / köper / en stol.','Bygg: hon / köper / en stol.'),'Hon köper en stol.',T('Hon — кто; köper — действие; en stol — покупка.','Hon — хто; köper — дія; en stol — покупка.','Hon is the subject, köper the verb and en stol the object.','Hon är subjekt, köper verb och en stol objekt.'))
 R('basics','dictionary',T('Как учить словарную форму','Як учити словникову форму','How to learn a dictionary form','Lär in uppslagsformen'),
 T('Начальная форма — обычно неопределённая форма единственного числа: bok, hus, äpple. В своей карточке добавляй артикль: en bok, ett hus, ett äpple.','Початкова форма — зазвичай неозначена форма однини: bok, hus, äpple. У своїй картці додавай артикль: en bok, ett hus, ett äpple.','The dictionary headword is normally the indefinite singular: bok, hus, äpple. Add an article on your own word card: en bok, ett hus, ett äpple.','Uppslagsformen är normalt obestämd singular: bok, hus, äpple. Lägg till artikel på ditt eget ordkort: en bok, ett hus, ett äpple.'),
 T('На svenska.se смотри род и формы: bok — boken — böcker — böckerna. Читай карточку вслух и добавляй предложение. Словарь может показывать окончания сокращённо: ~en означает boken.','На svenska.se дивись рід і форми: bok — boken — böcker — böckerna. Читай картку вголос і додавай речення. Словник може скорочувати закінчення: ~en означає boken.','On svenska.se check gender and inflections: bok — boken — böcker — böckerna. Read your card aloud and add a sentence. A dictionary may abbreviate endings: ~en stands for boken.','Kontrollera genus och böjning på svenska.se: bok — boken — böcker — böckerna. Läs kortet högt och lägg till en mening. Ordboken kan förkorta ändelsen: ~en står för boken.'),S('en bok → boken → böcker → böckerna → Jag läser en bok.'),[E('Jag behöver en penna.','Мне нужна ручка.','Мені потрібна ручка.','I need a pen.'),E('Vi behöver ett bord.','Нам нужен стол.','Нам потрібен стіл.','We need a table.')],T('Знать перевод bok недостаточно; знать en bok помогает строить boken и min bok.','Знати переклад bok замало; en bok допомагає будувати boken та min bok.','A translation alone is insufficient; en bok supports boken and min bok.','Översättningen räcker inte; en bok hjälper dig med boken och min bok.'),T('Не записывай huset как начальную форму. Ищи hus.','Не записуй huset як початкову форму. Шукай hus.','Do not use huset as the headword; look up hus.','Använd inte huset som uppslagsform; slå upp hus.'),T('Не у всех существительных есть обычные формы обоих чисел: vatten чаще обозначает вещество.','Не всі іменники мають звичайні форми обох чисел: vatten частіше позначає речовину.','Not every noun has ordinary forms in both numbers: vatten usually names a substance.','Alla substantiv används inte vanligt i båda numerus: vatten betecknar oftast ett ämne.'),T('Начальная форма для stolen?','Початкова форма для stolen?','What is the headword for stolen?','Vilken är uppslagsformen för stolen?'),'stol',T('Учи en stol; stolen — определённая форма.','Учи en stol; stolen — означена форма.','Learn en stol; stolen is the definite form.','Lär in en stol; stolen är bestämd form.'))
 R('gender','gender',T('Два грамматических рода','Два граматичні роди','Two grammatical genders','Två grammatiska genus'),
 T('В стандартном шведском два основных грамматических рода существительных: utrum (en-ord) и neutrum (ett-ord). Род — свойство слова, не пол предмета или человека.','У стандартній шведській два основні граматичні роди іменників: utrum (en-ord) та neutrum (ett-ord). Рід — властивість слова, не стать предмета чи людини.','Standard Swedish has two main noun genders: utrum (en-ord) and neutrum (ett-ord). Gender belongs to the word; it is not a person’s or object’s sex.','Standardsvenska har två huvudsakliga substantivgenus: utrum (en-ord) och neutrum (ett-ord). Genus är en egenskap hos ordet, inte personens eller sakens kön.'),
 T('Перед одним новым исчисляемым предметом используем en или ett по словарю. Разница проявляется и в других формах: bilen / huset, stor / stort. Меняя артикль, мы не меняем смысл слова на мужской или женский.','Перед одним новим злічуваним предметом уживаємо en або ett за словником. Різницю видно й в інших формах: bilen / huset, stor / stort. Зміна артикля не робить значення чоловічим чи жіночим.','For one new countable item use en or ett according to the dictionary. Gender also affects bilen / huset and stor / stort. Changing the article does not turn the meaning male or female.','Framför en ny räkningsbar sak används en eller ett enligt ordets genus. Det märks också i bilen / huset och stor / stort. Ett artikelbyte gör inte betydelsen manlig eller kvinnlig.'),S('utrum → en bil · neutrum → ett hus'),[E('Jag har en bil.','У меня есть машина.','Я маю машину.','I have a car.'),E('De har ett hus.','У них есть дом.','Вони мають будинок.','They have a house.')],T('En и ett оба вводят один предмет; это разные классы слов, а не разные количества.','En та ett обидва вводять один предмет; це різні класи слів, а не різна кількість.','En and ett both introduce a single item; they mark different noun classes, not quantities.','En och ett presenterar båda en enda sak; skillnaden gäller genus, inte antal.'),T('Ett bil → en bil. У bil род utrum.','Ett bil → en bil. Bil має рід utrum.','Ett bil must be en bil; bil is utrum.','Ett bil ska vara en bil; bil har utrum.'),T('Артикль не всегда написан, но род слова сохраняется.','Артикль не завжди написано, але рід слова зберігається.','A noun keeps its gender even when no article is written.','Ordet behåller sitt genus även utan synlig artikel.'),T('Какой артикль у hus?','Який артикль у hus?','Which article goes with hus?','Vilken artikel hör till hus?'),'ett',T('Запоминаем ett hus как единое сочетание.','Запам’ятовуємо ett hus як єдине сполучення.','Learn ett hus as one unit.','Lär in ett hus som en enhet.'))
 R('gender','translation',T('Перевод не предсказывает род','Переклад не передбачає рід','Translation does not predict gender','Översättningen förutsäger inte genus'),
 T('Русский или украинский род нельзя перенести в шведский. Английское a/an тоже не сообщает шведский род: an apple — ett äpple, a book — en bok.','Російський або український рід не можна переносити у шведську. Англійське a/an теж не показує шведського роду: an apple — ett äpple, a book — en bok.','Russian and Ukrainian gender does not transfer to Swedish. English a/an gives no Swedish gender information either: an apple — ett äpple; a book — en bok.','Genus i ryska eller ukrainska kan inte överföras till svenska. Engelska a/an anger inte heller svenskt genus: an apple — ett äpple; a book — en bok.'),
 T('«Стол/стіл» — мужской род в русском/украинском, но ett bord. «Книга/книжка» — женский, но en bok. Проверяй именно шведское слово: у синонимов тоже могут быть разные роды.','«Стол/стіл» — чоловічий рід у російській/українській, але ett bord. «Книга/книжка» — жіночий, але en bok. Перевіряй саме шведське слово: синоніми теж можуть мати різний рід.','Russian stol and Ukrainian stil are masculine, but Swedish has ett bord. Their feminine words for book correspond to en bok. Check the Swedish word itself: synonyms may also differ in gender.','Ryskans stol och ukrainskans stil är maskulina, men på svenska heter det ett bord. Deras feminina ord för bok motsvarar en bok. Kontrollera det svenska ordet: även synonymer kan ha olika genus.'),S('table → ett bord · book → en bok'),[E('Ett bord står här.','Здесь стоит стол.','Тут стоїть стіл.','A table stands here.'),E('En bok ligger där.','Там лежит книга.','Там лежить книжка.','A book is lying there.')],T('В английском a/an зависит от звука; en/ett — от рода.','В англійській a/an залежить від звука; en/ett — від роду.','English a/an depends on sound; Swedish en/ett depends on gender.','Engelska a/an beror på ljud; svenska en/ett beror på genus.'),T('Не выбирай en для bord из-за мужского рода перевода.','Не обирай en для bord через чоловічий рід перекладу.','Do not choose en for bord from the gender of its translation.','Välj inte en till bord utifrån översättningens genus.'),T('Совпадение в нескольких словах не создаёт правила.','Збіг у кількох словах не створює правила.','Several matching words do not establish a rule.','Några ord som stämmer överens skapar ingen regel.'),T('Исправь: en bord.','Виправ: en bord.','Correct: en bord.','Rätta: en bord.'),'ett bord',T('Словарная пара — ett bord.','Словникова пара — ett bord.','The dictionary pair is ett bord.','Ordet lärs in som ett bord.'))
 R('gender','people',T('Люди и животные: только тенденция','Люди й тварини: лише тенденція','People and animals: a tendency','Människor och djur: en tendens'),
 T('Многие названия людей и животных — en-ord: en lärare, en kvinna, en man, en hund, en katt. Но это не универсальное правило.','Багато назв людей і тварин — en-ord: en lärare, en kvinna, en man, en hund, en katt. Але це не універсальне правило.','Many words for people and animals are en-ord: en lärare, en kvinna, en man, en hund, en katt. This is not a universal rule.','Många ord för människor och djur är en-ord: en lärare, en kvinna, en man, en hund, en katt. Men det är ingen allmän regel.'),
 T('Важные ett-слова: ett barn, ett djur, ett syskon. Ребёнок любого пола — ett barn. Для конкретного человека выбирают личное местоимение по ситуации: hon, han или hen; род barn при этом не меняется.','Важливі ett-слова: ett barn, ett djur, ett syskon. Дитина будь-якої статі — ett barn. Для конкретної людини обирають займенник за ситуацією: hon, han або hen; рід barn не змінюється.','Important ett-words include ett barn, ett djur and ett syskon. A child of any sex is ett barn. Use hon, han or hen for a specific person as appropriate; barn keeps its gender.','Viktiga ett-ord är ett barn, ett djur och ett syskon. Barn har neutrum oavsett kön. Om en viss person används hon, han eller hen efter sammanhanget; barn behåller sitt genus.'),T('en person ≠ всё живое с en','en person ≠ усе живе з en','en person ≠ all living things use en','en person ≠ allt levande har en'),[E('Ett barn väntar här.','Здесь ждёт ребёнок.','Тут чекає дитина.','A child is waiting here.'),E('Hon har en hund.','У неё есть собака.','Вона має собаку.','She has a dog.')],T('En katt, но ett djur: вид и общее название могут различаться.','En katt, але ett djur: вид і загальна назва можуть відрізнятися.','En katt but ett djur: a species and a general label can differ.','En katt men ett djur: arten och det allmänna ordet kan ha olika genus.'),T('En barn → ett barn; «живое» не гарантирует en.','En barn → ett barn; «живе» не гарантує en.','En barn must be ett barn; being alive does not guarantee en.','En barn ska vara ett barn; levande betyder inte alltid en.'),T('Не заменяй автоматически hon/han на det только из-за ett barn.','Не замінюй автоматично hon/han на det лише через ett barn.','Do not automatically replace hon/han with det just because barn is neuter.','Byt inte automatiskt hon/han mot det bara för att barn har neutrum.'),T('Выбери словарную пару для «ребёнок».','Обери словникову пару для «дитина».','Give the word pair for child.','Ange ordparet för barn.'),'ett barn',T('Barn относится к neutrum.','Barn належить до neutrum.','Barn is neuter.','Barn har neutrum.'))
 R('gender','endings',T('Окончания как подсказка','Закінчення як підказка','Endings as clues','Ändelser som ledtrådar'),
 T('Некоторые словообразовательные суффиксы дают надёжную подсказку: существительные на -het и -ning обычно en-ord: en möjlighet, en tidning. Суффикс -ande/-ende в названиях действий и результатов часто даёт ett: ett meddelande.','Деякі словотвірні суфікси дають надійну підказку: іменники на -het і -ning зазвичай en-ord: en möjlighet, en tidning. Суфікс -ande/-ende у назвах дій і результатів часто дає ett: ett meddelande.','Some derivational suffixes are useful clues: nouns in -het and -ning are usually en-ord, such as en möjlighet and en tidning. Action/result nouns in -ande/-ende are often neuter: ett meddelande.','Vissa avledningssuffix ger bra ledtrådar: substantiv på -het och -ning är vanligen en-ord, som en möjlighet och en tidning. Handlings- och resultatord på -ande/-ende är ofta ett-ord: ett meddelande.'),
 T('Важен именно суффикс, а не последние буквы. En studerande называет человека. Многие слова на -a — en, например en lampa, но ett öga — ett. Не придумывай правило по одной букве.','Важливий саме суфікс, а не останні літери. En studerande називає людину. Багато слів на -a — en, як en lampa, але ett öga — ett. Не вигадуй правило за однією літерою.','The actual suffix matters, not merely the last letters. En studerande refers to a person. Many -a words are en, as in en lampa, but ett öga is neuter. Do not infer gender from a single letter.','Det är suffixet, inte bara de sista bokstäverna, som är viktigt. En studerande syftar på en person. Många ord på -a är en-ord, som en lampa, men ett öga är ett-ord. Dra ingen regel av en bokstav.'),T('-het / -ning → часто en; -a не гарантирует род','-het / -ning → часто en; -a не гарантує рід','-het / -ning → often en; -a alone is no guarantee','-het / -ning → ofta en; -a ensamt ger ingen garanti'),[E('Jag läser en tidning.','Я читаю газету.','Я читаю газету.','I am reading a newspaper.'),E('Du får ett meddelande.','Ты получаешь сообщение.','Ти отримуєш повідомлення.','You receive a message.')],T('En lampa и ett öga оканчиваются на a, но имеют разный род.','En lampa та ett öga закінчуються на a, але мають різний рід.','En lampa and ett öga both end in a but differ in gender.','En lampa och ett öga slutar båda på a men har olika genus.'),T('En meddelande → ett meddelande. Проверяй целое слово.','En meddelande → ett meddelande. Перевіряй ціле слово.','En meddelande should be ett meddelande. Check the whole word.','En meddelande ska vara ett meddelande. Kontrollera hela ordet.'),T('Подсказки облегчают запоминание, но не заменяют словарь.','Підказки полегшують запам’ятовування, але не замінюють словника.','Clues help memory but do not replace a dictionary.','Ledtrådar hjälper minnet men ersätter inte ordboken.'),T('Почему нельзя всегда выбирать en для слов на -a?','Чому не можна завжди обирати en для слів на -a?','Give a neuter counterexample to the -a clue.','Ge ett ett-ord som slutar på -a.'),'ett öga',T('Öga — ett-слово, хотя оканчивается на a.','Öga — ett-слово, хоча закінчується на a.','Öga is neuter despite ending in a.','Öga har neutrum trots a i slutet.'),level='B')
 R('gender','compounds',T('Сложные слова: смотри в конец','Складні слова: дивись у кінець','Compounds: check the final part','Sammansättningar: se på slutleden'),
 T('В обычных сложных существительных род определяется последней частью: ett rum → ett sovrum; en bok → en skolbok. Это полезнее, чем угадывать по теме слова.','У звичайних складних іменниках рід визначає остання частина: ett rum → ett sovrum; en bok → en skolbok. Це корисніше, ніж вгадувати за темою.','In ordinary noun compounds the last part determines gender: ett rum → ett sovrum; en bok → en skolbok. This is more useful than guessing from the topic.','I vanliga sammansatta substantiv bestämmer slutleden genus: ett rum → ett sovrum; en bok → en skolbok. Det hjälper mer än att gissa utifrån ämnet.'),
 T('Sovrum — разновидность rum, не разновидность действия sova. Пиши такие слова слитно. Учись видеть знакомую последнюю часть: köksbord заканчивается на bord, значит ett köksbord.','Sovrum — різновид rum, не різновид дії sova. Пиши такі слова разом. Шукай знайому останню частину: köksbord закінчується на bord, отже ett köksbord.','A sovrum is a kind of rum, not a kind of sleeping action. Write these compounds as one word. Köksbord ends in bord, so it is ett köksbord.','Ett sovrum är ett slags rum, inte en sorts handling. Skriv dessa sammansättningar som ett ord. Köksbord slutar på bord och blir därför ett köksbord.'),S('ett rum → ett sovrum · en bok → en skolbok'),[E('Vi har ett sovrum.','У нас есть спальня.','Ми маємо спальню.','We have a bedroom.'),E('Jag köper en skolbok.','Я покупаю учебник.','Я купую підручник.','I am buying a schoolbook.')],T('En skola, но ett skolhus: решает hus, а не skola.','En skola, але ett skolhus: вирішує hus, не skola.','En skola but ett skolhus: hus determines gender, not skola.','En skola men ett skolhus: hus avgör, inte skola.'),T('En sovrum → ett sovrum; sov rum → sovrum.','En sovrum → ett sovrum; sov rum → sovrum.','Use ett sovrum and write sovrum as one word.','Skriv ett sovrum och skriv sovrum som ett ord.'),T('Это надёжная основа для обычных сложных слов, но есть закреплённые исключения: en blick → ett ögonblick («взгляд» → «мгновение»). Незнакомое слово проверяй.','Це надійна основа для звичайних складних слів, але є усталені винятки: en blick → ett ögonblick («погляд» → «мить»). Незнайоме слово перевіряй.','This is a reliable guide to ordinary compounds, but lexicalised exceptions exist: en blick → ett ögonblick (a glance → a moment). Check unfamiliar words.','Det är en säker grund för vanliga sammansättningar, men lexikaliserade undantag finns: en blick → ett ögonblick. Kontrollera okända ord.'),T('Артикль для köksbord, если bord — ett?','Артикль для köksbord, якщо bord — ett?','Article for köksbord if bord is neuter?','Artikel till köksbord om bord är ett-ord?'),'ett',T('Последняя часть bord определяет род.','Остання частина bord визначає рід.','The final part bord determines gender.','Slutleden bord bestämmer genus.'),level='B')
 R('gender','variation',T('Варианты рода и значение','Варіанти роду й значення','Gender variation and meaning','Genusvariation och betydelse'),
 T('У большинства существительных один род, но у некоторых допустимы варианты, например en/ett test. Их нужно проверять в словаре; нельзя объявлять любой непривычный вариант ошибкой.','Більшість іменників має один рід, але деякі допускають варіанти, як en/ett test. Їх треба перевіряти у словнику; не кожен незвичний варіант є помилкою.','Most nouns have one gender, but some allow alternatives, such as en/ett test. Check these in the dictionary; an unfamiliar variant is not necessarily wrong.','De flesta substantiv har ett genus, men vissa tillåter variation, till exempel en/ett test. Kontrollera ordboken; en ovanlig variant behöver inte vara fel.'),
 T('В кафе en kaffe обычно означает порцию кофе. Для самого напитка употребляется kaffe без артикля, определённая форма обычно kaffet. Чтобы избежать сложности, начинай с en kopp kaffe.','У кафе en kaffe зазвичай означає порцію кави. Сам напій — kaffe без артикля, означена форма зазвичай kaffet. Щоб уникнути складності, почни з en kopp kaffe.','In a café en kaffe normally means a serving. For the substance use kaffe without an article; the ordinary definite form is kaffet. Begin with the clear expression en kopp kaffe.','På kafé betyder en kaffe vanligen en portion. Ämnet heter kaffe utan artikel och den vanliga bestämda formen är kaffet. Börja med det tydliga uttrycket en kopp kaffe.'),T('kaffe → вещество; en kopp kaffe → порция','kaffe → речовина; en kopp kaffe → порція','kaffe → a substance; en kopp kaffe → a serving','kaffe → ett ämne; en kopp kaffe → en portion'),[E('Jag dricker kaffe.','Я пью кофе.','Я п’ю каву.','I drink coffee.'),E('En kopp kaffe, tack.','Чашку кофе, пожалуйста.','Чашку кави, будь ласка.','A cup of coffee, please.')],T('En kaffe в заказе не доказывает, что у всех названий напитков род en.','En kaffe у замовленні не доводить, що всі напої мають рід en.','En kaffe in an order does not make every drink an en-word.','En kaffe i en beställning betyder inte att alla drycker är en-ord.'),T('Не считай ett test ошибкой: вариант нормативен.','Не вважай ett test помилкою: варіант нормативний.','Do not mark ett test wrong: it is standard.','Räkna inte ett test som fel: varianten är korrekt.'),T('В тесте этой главы нет вопросов, где выбор зависит от спорного или вариантного рода.','У тесті розділу немає питань, де відповідь залежить від спірного чи варіантного роду.','This chapter’s test does not force a choice between accepted gender variants.','Kapitlets test kräver inget val mellan godkända genusvarianter.'),T('Как явно заказать одну порцию кофе?','Як явно замовити одну порцію кави?','How can you clearly order one serving of coffee?','Hur beställer du tydligt en portion kaffe?'),'En kopp kaffe, tack.',T('Артикль относится к kopp — чашке.','Артикль стосується kopp — чашки.','The article belongs to kopp, cup.','Artikeln hör till kopp.'),level='B',sources=['isof-variation','saol'])
 R('usage','indefinite',T('Один новый предмет','Один новий предмет','One new item','En ny sak'),
 T('Obestämd form — неопределённая форма. En bok и ett hus представляют один исчисляемый объект, который собеседнику ещё не нужно узнавать как конкретный известный объект.','Obestämd form — неозначена форма. En bok та ett hus представляють один злічуваний об’єкт, який співрозмовник ще не має впізнавати як конкретний відомий об’єкт.','Obestämd form is the indefinite form. En bok and ett hus introduce one countable item that the listener is not yet expected to identify as a known item.','Obestämd form presenterar en räkningsbar sak som lyssnaren ännu inte förväntas identifiera som en viss känd sak.'),
 T('В магазине Jag behöver en stol говорит о потребности в стуле, а не об известном ранее стуле. Артикль — отдельное слово. Между ним и существительным может стоять прилагательное: en röd stol.','У магазині Jag behöver en stol означає потребу в стільці, а не у відомому раніше стільці. Артикль — окреме слово. Між ним та іменником може стояти прикметник: en röd stol.','In a shop Jag behöver en stol expresses a need for a chair rather than a previously identified chair. The article is a separate word. An adjective can come between article and noun: en röd stol.','I en butik anger Jag behöver en stol ett behov av en stol. Det behöver inte vara en tidigare känd stol. Artikeln är ett eget ord. Ett adjektiv kan stå emellan: en röd stol.'),S('en / ett → (adjektiv) → substantiv'),[E('Jag söker en lägenhet.','Я ищу квартиру.','Я шукаю квартиру.','I am looking for an apartment.'),E('Vi köper ett äpple.','Мы покупаем яблоко.','Ми купуємо яблуко.','We are buying an apple.')],T('En stol — новый стул; stolen — стул, который можно определить из ситуации.','En stol — новий стілець; stolen — стілець, який можна визначити із ситуації.','En stol introduces a chair; stolen identifies the chair from the situation.','En stol presenterar en stol; stolen kan identifieras i sammanhanget.'),T('Jag behöver stol → Jag behöver en stol, если речь об одном обычном стуле.','Jag behöver stol → Jag behöver en stol, якщо йдеться про один звичайний стілець.','For one ordinary chair use Jag behöver en stol, not Jag behöver stol.','Om en vanlig stol: Jag behöver en stol, inte Jag behöver stol.'),T('Не распространяй это на вещества, профессии и готовые выражения: дальше будут отдельные правила.','Не поширюй це на речовини, професії й сталі вислови: далі є окремі правила.','Do not extend this to substances, professions or fixed expressions; see the following rules.','Överför inte detta till ämnen, yrken och fasta uttryck; se nästa regler.'),T('Добавь артикль: Vi köper ___ stol.','Додай артикль: Vi köper ___ stol.','Add the article: Vi köper ___ stol.','Lägg till artikeln: Vi köper ___ stol.'),'en',T('Stol — исчисляемое en-слово в единственном числе.','Stol — злічуване en-слово в однині.','Stol is a countable en-word in the singular.','Stol är ett räkningsbart en-ord i singular.'))
 R('usage','reference',T('Первое упоминание и общая ситуация','Перша згадка й спільна ситуація','First mention and shared context','Första omnämnandet och sammanhanget'),
 T('Часто мы сначала говорим en bok, затем boken. Но важен смысл: может ли собеседник понять, какой предмет имеется в виду? Одного номера упоминания недостаточно.','Часто спершу кажемо en bok, потім boken. Але важливий зміст: чи співрозмовник розуміє, який предмет мається на увазі? Самого номера згадки замало.','We often say en bok first and boken later. Meaning matters: can the listener identify the item? Simply counting mentions is not enough.','Ofta säger vi först en bok och sedan boken. Men betydelsen avgör: kan lyssnaren identifiera saken? Det räcker inte att räkna omnämnanden.'),
 T('Jag köper en bok. Boken är dyr. Во второй фразе речь о той же книге. Stäng dörren! естественно и при первом упоминании, если обоим понятно, какая дверь.','Jag köper en bok. Boken är dyr. У другій фразі йдеться про ту саму книжку. Stäng dörren! природно й за першої згадки, якщо обом зрозуміло, які двері.','Jag köper en bok. Boken är dyr refers to the same book. Stäng dörren! is natural even at first mention if both people know which door is meant.','Jag köper en bok. Boken är dyr syftar på samma bok. Stäng dörren! fungerar även första gången dörren nämns om båda vet vilken dörr det gäller.'),S('en bok → samma bok → boken'),[E('Jag ser ett hus. Huset är rött.','Я вижу дом. Этот дом красный.','Я бачу будинок. Цей будинок червоний.','I see a house. The house is red.'),E('Stäng dörren, tack.','Закрой дверь, пожалуйста.','Зачини двері, будь ласка.','Close the door, please.')],T('Ny bok вводит объект; boken связывает его с общим знанием.','Ny bok вводить об’єкт; boken пов’язує його зі спільним знанням.','An indefinite noun introduces; boken links to shared knowledge.','Obestämd form presenterar; boken knyter an till gemensam kunskap.'),T('Не выбирай форму только потому, что слово встречается второй раз: новый предмет тоже может быть en bok.','Не обирай форму лише тому, що слово згадується вдруге: новий предмет теж може бути en bok.','A second use of the word can still be en bok if it introduces another book.','Andra gången ordet används kan det ändå vara en bok om det gäller en annan bok.'),T('Подробности определённости изучаются в уроке 6.','Подробиці означеності вивчаємо в уроці 6.','Lesson 6 develops definiteness in detail.','Bestämdhet behandlas mer i lektion 6.'),T('Та же книга: Jag har en bok. ___ är bra.','Та сама книжка: Jag har en bok. ___ är bra.','Same book: Jag har en bok. ___ är bra.','Samma bok: Jag har en bok. ___ är bra.'),'Boken',T('Собеседник уже может узнать эту книгу.','Співрозмовник уже може впізнати цю книжку.','The listener can now identify the book.','Lyssnaren kan nu identifiera boken.'))
 R('usage','mass',T('Вещества, еда и общие понятия','Речовини, їжа й загальні поняття','Substances, food and concepts','Ämnen, mat och begrepp'),
 T('Когда говорим о веществе или занятии вообще, артикля часто нет: Jag dricker vatten. Vi äter mat. Количество не представлено как один отдельный предмет.','Коли говоримо про речовину чи заняття загалом, артикля часто немає: Jag dricker vatten. Vi äter mat. Кількість не подано як один окремий предмет.','When speaking of a substance or activity generally, there is often no article: Jag dricker vatten. Vi äter mat. No single bounded item is being counted.','När vi talar om ett ämne eller en aktivitet allmänt saknas ofta artikel: Jag dricker vatten. Vi äter mat. Vi räknar ingen avgränsad sak.'),
 T('У vatten всё равно род ett: vattnet. Чтобы назвать порцию, добавь меру: ett glas vatten, en kopp kaffe. Артикль относится к glas или kopp. Tid и hjälp тоже часто употребляются без артикля: Jag behöver hjälp.','Vatten усе одно має рід ett: vattnet. Для порції додай міру: ett glas vatten, en kopp kaffe. Артикль належить до glas чи kopp. Tid та hjälp теж часто без артикля: Jag behöver hjälp.','Vatten remains neuter: vattnet. To specify a serving add a measure: ett glas vatten, en kopp kaffe. The article belongs to glas or kopp. Tid and hjälp often appear without articles too: Jag behöver hjälp.','Vatten har fortfarande neutrum: vattnet. Ange en portion med ett mått: ett glas vatten, en kopp kaffe. Artikeln hör till glas eller kopp. Tid och hjälp står också ofta utan artikel: Jag behöver hjälp.'),S('vatten → ett glas vatten · kaffe → en kopp kaffe'),[E('Jag vill ha vatten.','Я хочу воды.','Я хочу води.','I would like water.'),E('Hon behöver hjälp.','Ей нужна помощь.','Їй потрібна допомога.','She needs help.')],T('Ett äpple — считаем предмет; vatten — говорим о веществе.','Ett äpple — рахуємо предмет; vatten — говоримо про речовину.','Ett äpple counts an item; vatten refers to a substance.','Ett äpple räknar en sak; vatten anger ett ämne.'),T('Jag dricker en vatten — не базовая форма для воды вообще. Скажи Jag dricker vatten.','Jag dricker en vatten — не базова форма для води загалом. Скажи Jag dricker vatten.','For water in general use Jag dricker vatten, not Jag dricker en vatten.','Om vatten allmänt: Jag dricker vatten, inte Jag dricker en vatten.'),T('Заказ порции и название сорта могут менять конструкцию. Не запрещай артикль навсегда.','Замовлення порції й назва сорту можуть змінювати конструкцію. Не забороняй артикль назавжди.','A serving or variety may use a different construction; an article is not forbidden in every possible context.','En portion eller sort kan ge en annan konstruktion; artikel är inte förbjuden i alla sammanhang.'),T('Закажи стакан воды: ___ glas vatten.','Замов склянку води: ___ glas vatten.','Order a glass of water: ___ glas vatten.','Beställ ett glas vatten: ___ glas vatten.'),'ett',T('Glas — ett-слово; vatten обозначает содержимое.','Glas — ett-слово; vatten позначає вміст.','Glas is neuter; vatten gives the contents.','Glas är ett-ord; vatten anger innehållet.'))
 R('usage','profession',T('Профессия без артикля','Професія без артикля','Profession without an article','Yrke utan artikel'),
 T('После är или arbetar som название профессии обычно употребляется без en/ett: Hon är lärare. Jag arbetar som läkare. Это классификация по профессии.','Після är або arbetar som назва професії зазвичай без en/ett: Hon är lärare. Jag arbetar som läkare. Це класифікація за професією.','After är or arbetar som, a profession normally has no en/ett: Hon är lärare. Jag arbetar som läkare. This classifies someone by occupation.','Efter är eller arbetar som står yrkesord normalt utan en/ett: Hon är lärare. Jag arbetar som läkare. Det anger yrkestillhörighet.'),
 T('Но Jag träffar en lärare представляет человека. Hon är en bra lärare оценивает её как хорошего преподавателя и содержит артикль. Род lärare остаётся en во всех случаях.','Але Jag träffar en lärare представляє людину. Hon är en bra lärare оцінює її як хорошу викладачку й має артикль. Рід lärare всюди залишається en.','Jag träffar en lärare introduces a person. Hon är en bra lärare evaluates her as a good teacher and has an article. Lärare retains en-gender in each case.','Jag träffar en lärare presenterar en person. Hon är en bra lärare värderar henne som lärare och har artikel. Lärare behåller sitt genus i alla fallen.'),S('är / arbetar som → lärare · träffar → en lärare'),[E('Min granne är läkare.','Мой сосед — врач.','Мій сусід — лікар.','My neighbour is a doctor.'),E('Hon är en bra lärare.','Она хороший преподаватель.','Вона хороша викладачка.','She is a good teacher.')],T('Är lärare — профессия; har en lärare — есть преподаватель.','Är lärare — професія; har en lärare — є викладач.','Är lärare gives a profession; har en lärare means having a teacher.','Är lärare anger yrke; har en lärare anger att man undervisas.'),T('Не переноси отсутствие артикля в Hon är lärare на Jag behöver en penna.','Не перенось відсутність артикля в Hon är lärare на Jag behöver en penna.','The profession pattern does not license omitting en in Jag behöver en penna.','Yrkesmönstret tar inte bort en i Jag behöver en penna.'),T('С артиклем иногда меняется оттенок смысла, а не только правильность.','З артиклем іноді змінюється відтінок значення, а не лише правильність.','An article can change the emphasis rather than simply making a sentence wrong.','En artikel kan ändra betoningen i betydelsen, inte bara göra meningen fel.'),T('Назови только профессию: Hon är ___. (lärare)','Назви лише професію: Hon är ___. (lärare)','State only the profession: Hon är ___. (lärare)','Ange bara yrket: Hon är ___. (lärare)'),'lärare',T('Для нейтрального названия профессии артикль не нужен.','Для нейтральної назви професії артикль не потрібен.','The neutral profession label needs no article.','Den neutrala yrkesbeteckningen behöver ingen artikel.'))
 R('usage','determiners',T('Числа и слова принадлежности','Числа й слова належності','Numbers and possession','Tal och ägande'),
 T('После två не ставим en/ett: två böcker. После min/mitt тоже нет неопределённого артикля: min bok, mitt hus. Эти слова уже определяют сочетание.','Після två не ставимо en/ett: två böcker. Після min/mitt теж немає неозначеного артикля: min bok, mitt hus. Ці слова вже визначають сполучення.','Do not add en/ett after två: två böcker. Possessives also replace the indefinite article: min bok, mitt hus. These words already determine the noun phrase.','Efter två används inte en/ett: två böcker. Inte heller efter min/mitt: min bok, mitt hus. Dessa ord bestämmer redan nominalfrasen.'),
 T('Min согласуется с en-словом, mitt — с ett-словом. Существительное после них без определённого окончания: min bok, не min boken. Это связь с уроком о местоимениях, не новая форма рода.','Min узгоджується з en-словом, mitt — з ett-словом. Іменник після них без означеного закінчення: min bok, не min boken. Це зв’язок з уроком про займенники, не новий рід.','Min agrees with en-words and mitt with ett-words. The noun takes no definite suffix after these: min bok, not min boken. This connects to the pronoun lesson.','Min hör till en-ord och mitt till ett-ord. Substantivet har ingen bestämd ändelse efter dem: min bok, inte min boken. Det knyter an till lektionen om pronomen.'),S('min bok · mitt hus · två böcker'),[E('Mitt rum är stort.','Моя комната большая.','Моя кімната велика.','My room is large.'),E('Jag har två stolar.','У меня два стула.','Я маю два стільці.','I have two chairs.')],T('En bok — одна новая книга; min bok — моя книга; två böcker — две книги.','En bok — одна нова книжка; min bok — моя книжка; två böcker — дві книжки.','En bok is a new book; min bok is my book; två böcker is two books.','En bok presenterar en bok; min bok anger ägande; två böcker anger antal.'),T('Min en bok → min bok; mitt huset → mitt hus.','Min en bok → min bok; mitt huset → mitt hus.','Use min bok, not min en bok; mitt hus, not mitt huset.','Skriv min bok, inte min en bok; mitt hus, inte mitt huset.'),T('Не применяй правило отсутствия окончания после min ко всем определяющим словам: den här boken — другая конструкция.','Не поширюй правило після min на всі означальні слова: den här boken — інша конструкція.','Do not extend the min pattern to every determiner: den här boken is a different construction.','Överför inte mönstret efter min till alla bestämningar: den här boken är en annan konstruktion.'),T('Исправь: mitt huset.','Виправ: mitt huset.','Correct: mitt huset.','Rätta: mitt huset.'),'mitt hus',T('После mitt используется hus без -et.','Після mitt уживаємо hus без -et.','After mitt use hus without -et.','Efter mitt används hus utan -et.'))
 R('forms','definite',T('Определённая форма: первые шаги','Означена форма: перші кроки','Definite form: first steps','Bestämd form: första steg'),
 T('Когда предмет можно узнать из контекста, часто используется bestämd form. У многих en-слов добавляется -en, у многих ett-слов -et: bok → boken, hus → huset.','Коли предмет можна впізнати з контексту, часто вживаємо bestämd form. У багатьох en-слів додається -en, у багатьох ett-слів -et: bok → boken, hus → huset.','When an item is identifiable in context, we often use bestämd form. Many en-words add -en and many ett-words add -et: bok → boken; hus → huset.','När saken går att identifiera i sammanhanget används ofta bestämd form. Många en-ord får -en och många ett-ord -et: bok → boken; hus → huset.'),
 T('После гласной окончание часто сокращается: en lampa → lampan; ett äpple → äpplet. Артикль en/ett перед этой простой определённой формой не сохраняется. Учи пару целиком.','Після голосної закінчення часто скорочується: en lampa → lampan; ett äpple → äpplet. Артикль en/ett перед цією простою означеною формою не зберігається. Учи цілу пару.','After a vowel the ending is often shorter: en lampa → lampan; ett äpple → äpplet. Do not retain en/ett before this simple definite form. Learn the whole pair.','Efter vokal är ändelsen ofta kortare: en lampa → lampan; ett äpple → äpplet. En/ett står inte kvar framför den enkla bestämda formen. Lär in hela paret.'),S('en bok → boken · en stol → stolen · ett hus → huset'),[E('Boken ligger här.','Книга лежит здесь.','Книжка лежить тут.','The book is lying here.'),E('Äpplet är rött.','Яблоко красное.','Яблуко червоне.','The apple is red.')],T('Ett hus — a house; huset — the house. В RU/UK выбор передаётся контекстом.','Ett hus — a house; huset — the house. У RU/UK вибір передає контекст.','Ett hus corresponds to a house; huset to the house. Other languages may express this through context.','Ett hus presenterar; huset identifierar. Andra språk kan uttrycka skillnaden genom sammanhanget.'),T('Ett huset → huset; boket → boken.','Ett huset → huset; boket → boken.','Use huset, not ett huset; boken, not boket.','Skriv huset, inte ett huset; boken, inte boket.'),T('Это введение. Особые окончания и полные конструкции с прилагательными — в следующих уроках.','Це вступ. Особливі закінчення й повні конструкції з прикметниками — у наступних уроках.','This is an introduction. Special endings and full definite adjective phrases come later.','Detta är en introduktion. Särskilda ändelser och bestämda adjektivfraser kommer senare.'),T('Определённая форма en stol?','Означена форма en stol?','Definite form of en stol?','Bestämd form av en stol?'),'stolen',T('Stol + en → stolen.','Stol + en → stolen.','Stol + en gives stolen.','Stol + en blir stolen.'))
 R('forms','boundaries',T('Название, предмет и указание','Назва, предмет і вказівка','A label, an item and pointing','En benämning, en sak och utpekande'),
 T('На этикетке может быть просто Stol: это название. В предложении об одном новом предмете обычно en stol. Когда указываем на определённый стул: den här stolen.','На етикетці може бути просто Stol: це назва. У реченні про один новий предмет зазвичай en stol. Коли вказуємо на певний стілець: den här stolen.','A label may simply say Stol. A sentence about one new item normally uses en stol. To point to a particular chair use den här stolen.','En etikett kan bara säga Stol. En mening om en ny sak har normalt en stol. När du pekar ut en viss stol: den här stolen.'),
 T('Den här сочетается с en-словами, det här — с ett-словами, существительное имеет определённое окончание: det här huset. Но Det här är en stol — другая схема: «Это стул», определение типа предмета.','Den här поєднується з en-словами, det här — з ett-словами, іменник має означене закінчення: det här huset. Але Det här är en stol — інша схема: «Це стілець», визначення типу предмета.','Den här goes with en-words and det här with ett-words, followed by a definite noun: det här huset. Det här är en stol is a different pattern identifying the type of object: This is a chair.','Den här hör till en-ord och det här till ett-ord, med bestämt substantiv: det här huset. Det här är en stol är ett annat mönster som anger vad saken är.'),S('en stol → den här stolen · ett hus → det här huset'),[E('Den här stolen är ledig.','Этот стул свободен.','Цей стілець вільний.','This chair is free.'),E('Det här är ett bord.','Это стол.','Це стіл.','This is a table.')],T('Det här är en stol называет тип; den här stolen указывает на стул.','Det här är en stol називає тип; den här stolen вказує на стілець.','Det här är en stol names the type; den här stolen points to the chair.','Det här är en stol anger typen; den här stolen pekar ut stolen.'),T('Den här stol → den här stolen; en stolen → en stol или stolen по смыслу.','Den här stol → den här stolen; en stolen → en stol або stolen за змістом.','Use den här stolen. Replace en stolen with en stol or stolen as meaning requires.','Skriv den här stolen. Byt en stolen mot en stol eller stolen efter betydelsen.'),T('Den/det + прилагательное + существительное изучается отдельно; здесь достаточно этих двух схем.','Den/det + прикметник + іменник вивчаємо окремо; тут достатньо цих двох схем.','Definite adjective phrases are studied separately; focus on these two patterns here.','Bestämda adjektivfraser studeras separat; här räcker de två mönstren.'),T('Укажи на этот дом: det här ___.','Укажи на цей будинок: det här ___.','Point to this house: det här ___.','Peka ut detta hus: det här ___.'),'huset',T('После det här в этой группе — определённая форма.','Після det här у цій групі — означена форма.','This noun phrase takes the definite form after det här.','I denna nominalfras används bestämd form efter det här.'),level='B')
 R('forms','plural',T('Один и несколько','Один і кілька','One and several','En och flera'),
 T('Singular — единственное число, plural — множественное. Во множественном числе неопределённого артикля en/ett нет: en bok → böcker, ett hus → hus, ett äpple → äpplen.','Singular — однина, plural — множина. У множині неозначеного артикля en/ett немає: en bok → böcker, ett hus → hus, ett äpple → äpplen.','Singular means one; plural means more than one. The plural has no indefinite en/ett: en bok → böcker; ett hus → hus; ett äpple → äpplen.','Singular gäller en och plural flera. I plural finns ingen obestämd artikel en/ett: en bok → böcker; ett hus → hus; ett äpple → äpplen.'),
 T('Начальные группы: -or (lampor), -ar (stolar), -er (böcker с изменением гласной), -n (äpplen), без окончания (hus). Есть и -r: en sko → skor. Род один не позволяет предсказать все формы: учи словарный plural.','Початкові групи: -or (lampor), -ar (stolar), -er (böcker зі зміною голосної), -n (äpplen), без закінчення (hus). Є й -r: en sko → skor. Сам рід не передбачає всіх форм: учи словниковий plural.','Initial groups include -or (lampor), -ar (stolar), -er (böcker with a vowel change), -n (äpplen), and no ending (hus). There is also -r: en sko → skor. Gender alone cannot predict every plural; learn it from the dictionary.','Några grupper är -or (lampor), -ar (stolar), -er (böcker med vokalbyte), -n (äpplen) och ingen ändelse (hus). Även -r finns: en sko → skor. Genus ensamt räcker inte för att förutsäga plural; lär in ordbokens form.'),S('en lampa → två lampor · ett barn → två barn'),[E('Vi har två böcker.','У нас две книги.','Ми маємо дві книжки.','We have two books.'),E('Tre äpplen ligger här.','Здесь лежат три яблока.','Тут лежать три яблука.','Three apples are lying here.')],T('Hus может быть singular или plural; ett/två и контекст показывают число.','Hus може бути одниною чи множиною; ett/två та контекст показують число.','Hus can be singular or plural; ett/två and context show number.','Hus kan vara singular eller plural; ett/två och sammanhanget visar antalet.'),T('Två en böcker → två böcker; två husar → två hus.','Två en böcker → två böcker; två husar → två hus.','Use två böcker and två hus, not två en böcker or två husar.','Skriv två böcker och två hus, inte två en böcker eller två husar.'),T('Это обзор, не полный курс plural. Не образуй все формы по одному образцу.','Це огляд, не повний курс plural. Не утворюй усі форми за одним зразком.','This is an overview, not a full plural course. Do not apply one ending to every noun.','Det är en översikt, inte en hel pluralkurs. Använd inte en ändelse för alla ord.'),T('Два яблока: två ___.','Два яблука: två ___.','Two apples: två ___.','Två äpplen: två ___.'),'äpplen',T('Ett äpple → äpplen с -n.','Ett äpple → äpplen із -n.','Ett äpple forms äpplen with -n.','Ett äpple får plural äpplen med -n.'))
 R('forms','adjectives',T('Прилагательное согласуется','Прикметник узгоджується','The adjective agrees','Adjektivet böjs'),
 T('Прилагательное описывает существительное. В простой неопределённой группе en-слово получает базовую форму, ett-слово часто форму на -t: en stor bil, ett stort hus.','Прикметник описує іменник. У простій неозначеній групі en-слово має базову форму, ett-слово часто форму на -t: en stor bil, ett stort hus.','An adjective describes a noun. In a simple indefinite phrase an en-word takes the base adjective and an ett-word often the -t form: en stor bil, ett stort hus.','Ett adjektiv beskriver ett substantiv. I en enkel obestämd fras har en-ord grundformen och ett-ord ofta t-formen: en stor bil, ett stort hus.'),
 T('Röd → rött: en röd stol, ett rött äpple. Согласование действует и после är: huset är stort. Начни с этих пар; подробные формы и исключения прилагательных будут в отдельном уроке.','Röd → rött: en röd stol, ett rött äpple. Узгодження діє й після är: huset är stort. Почни з цих пар; докладні форми й винятки прикметників будуть в окремому уроці.','Röd becomes rött: en röd stol, ett rött äpple. Agreement also applies after är: huset är stort. Start with these pairs; adjective details and exceptions come in a separate lesson.','Röd blir rött: en röd stol, ett rött äpple. Böjningen gäller också efter är: huset är stort. Börja med dessa par; detaljer och undantag kommer i en egen lektion.'),S('en → stor / röd · ett → stort / rött'),[E('Jag köper en röd stol.','Я покупаю красный стул.','Я купую червоний стілець.','I am buying a red chair.'),E('Han äter ett rött äpple.','Он ест красное яблоко.','Він їсть червоне яблуко.','He is eating a red apple.')],T('Stol — что это; röd — какой. Род задаёт существительное, не цвет.','Stol — що це; röd — який. Рід задає іменник, не колір.','Stol names the item; röd describes it. The noun determines gender, not the colour.','Stol benämner saken; röd beskriver den. Substantivet bestämmer genus, inte färgen.'),T('Ett stor hus → ett stort hus; en rött stol → en röd stol.','Ett stor hus → ett stort hus; en rött stol → en röd stol.','Use ett stort hus and en röd stol.','Skriv ett stort hus och en röd stol.'),T('Не все прилагательные просто добавляют t: röd меняет d на tt.','Не всі прикметники просто додають t: röd змінює d на tt.','Not every adjective simply adds t: röd changes d to tt.','Alla adjektiv lägger inte bara till t: röd byter d mot tt.'),T('Вставь stor: ett ___ hus.','Встав stor: ett ___ hus.','Insert stor: ett ___ hus.','Sätt in stor: ett ___ hus.'),'stort',T('Hus — ett-слово, поэтому stort.','Hus — ett-слово, тому stort.','Hus is neuter, so use stort.','Hus är ett-ord, därför stort.'))
 R('reference','exceptions',T('Частые ловушки','Часті пастки','Common traps','Vanliga fallgropar'),
 T('Запомни вместе: ett barn, ett djur, ett öga, ett äpple, ett bord. Ни живое существо, ни последняя буква, ни русский перевод не гарантируют en.','Запам’ятай разом: ett barn, ett djur, ett öga, ett äpple, ett bord. Ні жива істота, ні остання літера, ні переклад не гарантують en.','Learn these together: ett barn, ett djur, ett öga, ett äpple, ett bord. Neither being alive, a final letter nor a translation guarantees en.','Lär in dessa tillsammans: ett barn, ett djur, ett öga, ett äpple, ett bord. Varken liv, slutbokstav eller översättning garanterar en.'),
 T('Особые формы тоже хранятся со словом: en bok → böcker; ett fönster → fönstret. В fönstret исчезает безударное e. Не создавай собственные формы bokar или fönsteret.','Особливі форми теж зберігаємо зі словом: en bok → böcker; ett fönster → fönstret. У fönstret зникає ненаголошене e. Не створюй власні форми bokar чи fönsteret.','Store special forms with the word too: en bok → böcker; ett fönster → fönstret. Fönstret drops an unstressed e. Do not invent bokar or fönsteret.','Lär också in särskilda former: en bok → böcker; ett fönster → fönstret. I fönstret faller ett obetonat e bort. Skapa inte bokar eller fönsteret.'),S('ett fönster → fönstret · en bok → böcker'),[E('Fönstret är öppet.','Окно открыто.','Вікно відчинене.','The window is open.'),E('Barnet har två böcker.','У ребёнка две книги.','Дитина має дві книжки.','The child has two books.')],T('En bil → bilar, но en bok → böcker: одинаковый род не означает одинаковый plural.','En bil → bilar, але en bok → böcker: однаковий рід не означає однаковий plural.','En bil → bilar but en bok → böcker: shared gender does not imply the same plural.','En bil → bilar men en bok → böcker: samma genus ger inte samma plural.'),T('En barn и en bord исправляются по словарю, не по смыслу «человек» и «предмет».','En barn та en bord виправляємо за словником, не за змістом «людина» й «предмет».','Correct en barn and en bord using the dictionary, not person/object categories.','Rätta en barn och en bord med hjälp av ordboken, inte kategorierna person/sak.'),T('Слова с двумя нормативными родами, например test, не входят в эту группу ошибок.','Слова з двома нормативними родами, як test, не належать до цієї групи помилок.','Words with two accepted genders, such as test, are not errors of this kind.','Ord med två godkända genus, som test, är inte fel av detta slag.'),T('Исправь форму окна: fönsteret.','Виправ форму вікна: fönsteret.','Correct the window form: fönsteret.','Rätta formen: fönsteret.'),'fönstret',T('Учи пару ett fönster — fönstret.','Учи пару ett fönster — fönstret.','Learn the pair ett fönster — fönstret.','Lär in paret ett fönster — fönstret.'))
 R('reference','checklist',T('Шпаргалка и стратегия','Шпаргалка й стратегія','Reference and learning strategy','Snabbguide och strategi'),
 T('Сначала узнай слово и его род. Затем выбери смысл: новый предмет, известный предмет, количество или вещество. После этого проверь форму существительного и прилагательного.','Спершу впізнай слово та його рід. Потім обери зміст: новий предмет, відомий предмет, кількість чи речовина. Після цього перевір форму іменника й прикметника.','First identify the noun and gender. Then choose the meaning: new item, known item, quantity or substance. Finally check noun and adjective forms.','Identifiera först substantivet och dess genus. Välj sedan betydelsen: ny sak, känd sak, antal eller ämne. Kontrollera till sist substantivets och adjektivets form.'),
 T('Учи маленькими наборами по ситуации: en stol, ett bord, en lampa. Произнеси, закрой подсказку, опиши свою комнату, проверь по словарю. Ошибку исправляй целой фразой и повторяй позже.','Учи малими наборами за ситуацією: en stol, ett bord, en lampa. Вимов, закрий підказку, опиши свою кімнату, перевір у словнику. Помилку виправляй цілою фразою й повторюй пізніше.','Learn small sets by situation: en stol, ett bord, en lampa. Say them, hide the clue, describe your room and check a dictionary. Correct a mistake as a whole phrase and revisit it later.','Lär in små grupper efter situation: en stol, ett bord, en lampa. Säg orden, dölj stödet, beskriv rummet och kontrollera ordboken. Rätta fel med en hel fras och repetera senare.'),S('ord + genus → betydelse → form → mening → kontroll'),[E('I mitt rum finns ett bord.','В моей комнате есть стол.','У моїй кімнаті є стіл.','There is a table in my room.'),E('Bordet är stort.','Стол большой.','Стіл великий.','The table is large.')],T('Список помогает памяти, связный текст показывает применение. Нужны оба вида работы.','Список допомагає пам’яті, зв’язний текст показує застосування. Потрібні обидва види роботи.','Lists support memory; connected writing shows application. Practise both.','Listor stöder minnet; sammanhängande text visar användningen. Träna båda.'),T('Не меняй только артикль в ett stor bil: нужно en stor bil.','Не змінюй лише артикль у ett stor bil: потрібно en stor bil.','Check the whole phrase: ett stor bil becomes en stor bil.','Kontrollera hela frasen: ett stor bil blir en stor bil.'),T('Свободный текст требует самопроверки или учителя. Эта глава не ставит ему автоматическую оценку.','Вільний текст потребує самоперевірки чи вчителя. Розділ не виставляє йому автоматичної оцінки.','Free writing needs self-review or a teacher; this chapter does not automatically grade it.','Fri text kräver egen kontroll eller en lärare; kapitlet betygsätter den inte automatiskt.'),T('Какой предмет уже известен: Jag köper ett bord. ___ är stort.','Який предмет уже відомий: Jag köper ett bord. ___ är stort.','Refer to the known item: Jag köper ett bord. ___ är stort.','Syfta på den kända saken: Jag köper ett bord. ___ är stort.'),'Bordet',T('Сначала ett bord, затем тот же предмет — bordet.','Спершу ett bord, потім той самий предмет — bordet.','First ett bord; then the same item is bordet.','Först ett bord, sedan samma sak: bordet.'))
